@@ -0,0 +1,50 @@
+export class IdempotencyStore {
+  private store = new Map<string, { status: string; result?: unknown }>();
+
+  async process(key: string, fn: () => Promise<unknown>) {
+    if (this.store.has(key)) {
+      return this.store.get(key)!;
+    }
+
+    const result = await fn();
+    this.store.set(key, { status: 'completed', result });
+    return { status: 'completed', result };
+  }
+
+  async getStatus(key: string) {
+    return this.store.get(key) ?? { status: 'not_found' };
+  }
+}
